import 'package:flutter/material.dart';import 'package:sehatak/core/models/child/child_models.dart';import 'package:sehatak/core/services/child_service.dart';class ChildDoctorDetailScreen extends StatelessWidget{final String doctorId;const ChildDoctorDetailScreen({super.key,required this.doctorId});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('تفاصيل طبيب الأطفال')),body:FutureBuilder<ChildDoctor?>(future:ChildService().getDoctor(doctorId),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final d=s.data!;return ListView(padding:const EdgeInsets.all(20),children:[Center(child:CircleAvatar(radius:50,backgroundImage:d.photoUrl.isNotEmpty?NetworkImage(d.photoUrl):null,child:d.photoUrl.isEmpty?const Icon(Icons.person,size:45):null)),const SizedBox(height:15),Text(d.name,textAlign:TextAlign.center,style:const TextStyle(fontSize:22,fontWeight:FontWeight.w800)),Text(d.specialty,textAlign:TextAlign.center),Text('التقييم ${d.rating.toStringAsFixed(1)} • ${d.reviewCount} تقييم'),Text('الخبرة ${d.experienceYears} سنة'),Text('العنوان: ${d.address}'),Text('الهاتف: ${d.phone}')]);}));}}
